#------------Eye Detection------------------------------
class EyeDetection:
    def __init__(self, shape_predictor_path, ui):
        self.detector = dlib.get_frontal_face_detector()
        self.predictor = dlib.shape_predictor(shape_predictor_path)
        self.font = cv2.FONT_HERSHEY_COMPLEX
#--------------initiating ui-------------------------------
        #self.ui = ui
#----------current button to navigate buttons-----------------
        self.current_btn = 0
        self.left_frame = 0
        self.right_frame = 0
        self.blinking_frame = 0

    @staticmethod
    def midpoint(p1, p2):
        return int((p1.x + p2.x) / 2), int((p1.y + p2.y) / 2)

    def get_blinking_ratio(self, eye_points, facial_landmarks):
        right_point = (facial_landmarks.part(eye_points[0]).x, facial_landmarks.part(eye_points[0]).y)
        left_point = (facial_landmarks.part(eye_points[3]).x, facial_landmarks.part(eye_points[3]).y)
        center_top = self.midpoint(facial_landmarks.part(eye_points[1]), facial_landmarks.part(eye_points[2]))
        bottom_top = self.midpoint(facial_landmarks.part(eye_points[5]), facial_landmarks.part(eye_points[4]))

        hor_line_length = hypot((left_point[0] - right_point[0]), (left_point[1] - right_point[1]))
        ver_line_length = hypot((center_top[0] - bottom_top[0]), (center_top[1] - bottom_top[1]))

        return hor_line_length / ver_line_length

    def get_gaze_ratio(self, eye_points, facial_landmarks, frame, gray):
        eye_region = np.array([
            (facial_landmarks.part(eye_points[0]).x, facial_landmarks.part(eye_points[0]).y),
            (facial_landmarks.part(eye_points[1]).x, facial_landmarks.part(eye_points[1]).y),
            (facial_landmarks.part(eye_points[2]).x, facial_landmarks.part(eye_points[2]).y),
            (facial_landmarks.part(eye_points[3]).x, facial_landmarks.part(eye_points[3]).y),
            (facial_landmarks.part(eye_points[4]).x, facial_landmarks.part(eye_points[4]).y),
            (facial_landmarks.part(eye_points[5]).x, facial_landmarks.part(eye_points[5]).y)
        ])

        height, width, _ = frame.shape
        mask = np.zeros((height, width), np.uint8)
        cv2.polylines(mask, [eye_region], True, 255, 2)
        cv2.fillPoly(mask, [eye_region], 255)

        eye = cv2.bitwise_and(gray, gray, mask=mask)

        min_x = np.min(eye_region[:, 0])
        max_x = np.max(eye_region[:, 0])
        min_y = np.min(eye_region[:, 1])
        max_y = np.max(eye_region[:, 1])

        gray_eye = eye[min_y:max_y, min_x:max_x]
        _, threshold_eye = cv2.threshold(gray_eye, 70, 255, cv2.THRESH_BINARY)

        height, width = threshold_eye.shape
        left_side_threshold = threshold_eye[0:height, 0:int(width / 2)]
        right_side_threshold = threshold_eye[0:height, int(width / 2):width]

        left_side_white = cv2.countNonZero(left_side_threshold)
        right_side_white = cv2.countNonZero(right_side_threshold)

        return left_side_white / (right_side_white + 0.000000001)

    def process_frame(self, frame):
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        faces = self.detector(gray)

        for face in faces:
            #self.ui.update_highlight(self.current_btn)

            landmarks = self.predictor(gray, face)

            left_eye_ratio = self.get_blinking_ratio([36, 37, 38, 39, 40, 41], landmarks)
            right_eye_ratio = self.get_blinking_ratio([42, 43, 44, 45, 46, 47], landmarks)
            blinking_ratio = (left_eye_ratio + right_eye_ratio) / 2

            if blinking_ratio > 5.7:
                cv2.putText(frame, "BLINKING", (50, 150), self.font, 3, (255, 255, 0))
                self.blinking_frame += 1
                #if(self.blinking_frame > 10):
                     #self.ui.word1.setText(f"{self.current_btn}")
            else:
                self.blinking_frame = 0
                #made the gaze detection inside the else using one tab space--undo if needed
                gaze_ratio_left_eye = self.get_gaze_ratio([36, 37, 38, 39, 40, 41], landmarks, frame, gray)
                gaze_ratio_right_eye = self.get_gaze_ratio([42, 43, 44, 45, 46, 47], landmarks, frame, gray)
                gaze_ratio = (gaze_ratio_left_eye + gaze_ratio_right_eye) / 2

                if gaze_ratio < 1:
                        cv2.putText(frame, "RIGHT", (50, 100), self.font, 2, (0, 0, 255), 3)
                        #when left we need to do left transition over the buttons
                        #self.ui.update_text_area("Looking RIGHT")


                        #moving nav btn with time lag
                        self.left_frame = 0
                        self.right_frame += 1
                        if(self.right_frame>10):
                                self.right_frame = 0
                                if(self.current_btn <= 3 ):
                                        self.current_btn+=1
                
                        '''
                        if(self.frame_count!=0):
                        self.frame_count=0
                        else:
                        self.frame_count +=1
                        self.ui.word1.setText(f"{self.frame_count}")
                        '''

                        

                elif 1 < gaze_ratio < 3:
                        cv2.putText(frame, "CENTER", (50, 100), self.font, 2, (255, 0, 255), 3)
                        self.left_frame = 0
                        self.right_frame = 0
                else:
                        cv2.putText(frame, "LEFT", (50, 100), self.font, 2, (0, 255, 255), 3)
                        #self.ui.update_text_area("Looking LEFT")
                        
                        #moving nav btn with time lag
                        self.right_frame=0
                        self.left_frame+=1
                        if(self.left_frame>10):
                                self.left_frame = 0
                                if(self.current_btn != 0):
                                        self.current_btn-=1

        return frame


